def opt = { String k -> if (!binding.hasVariable(k)) return ''
                        def v = binding.getVariable(k); return (v == null) ? '' : v.toString().trim() }
def raw = { String k -> binding.hasVariable(k) ? binding.getVariable(k) : null }
def s = opt('search'); def fStatus = opt('status'); def fPeriod = opt('periodId')
def lim = opt('limit'); def off = opt('offset')
def wire = raw('filter')

boolean valid = true; String reason = ''
int pageLimit = 50
if (!lim.isEmpty()) { if (lim ==~ /^\d+$/) pageLimit = Integer.parseInt(lim) else { valid=false; reason='limit must be a whole number, got: ' + lim } }
if (pageLimit < 1) pageLimit = 1
if (pageLimit > 200) pageLimit = 200
int pageOffset = 0
if (!off.isEmpty()) { if (off ==~ /^\d+$/) pageOffset = Integer.parseInt(off) else { valid=false; reason='offset must be a whole number, got: ' + off } }

def leaves = []
if (!s.isEmpty()) leaves << [operator:'OR', filters:[
    [property:'properties.name',   filter:[operator:'ICONTAINS', value:s]],
    [property:'properties.planId', filter:[operator:'ICONTAINS', value:s]]]]
if (!fStatus.isEmpty()) leaves << [property:'properties.status',   filter:[operator:'EQUAL', value:fStatus]]
if (!fPeriod.isEmpty()) leaves << [property:'properties.periodId', filter:[operator:'EQUAL', value:fPeriod]]

// The caller's own filter, translated from the platform wire shape into the storage
// shape the fetch speaks. Every field here is stored ON the row, so all of it narrows
// server-side and paging stays exact.
def FIELDS = [planId:'TEXT', name:'TEXT', description:'TEXT', status:'TEXT', periodId:'TEXT',
              startDate:'DATE', endDate:'DATE', version:'NUMBER']
def TEXT_OPS = ['EQUAL','NOT_EQUAL','ICONTAINS','NOT_ICONTAINS','CONTAINS','NOT_CONTAINS','STARTS_WITH','NOT_STARTS_WITH','ENDS_WITH','NOT_ENDS_WITH','IN','NOT_IN'] as Set
def NUM_OPS  = ['EQUAL','NOT_EQUAL','GT','GTE','LT','LTE'] as Set
def DATE_OPS = ['EQUAL','GT','GTE','LT','LTE','BETWEEN'] as Set
def problems = []
def toLeaf
toLeaf = { node, String path ->
    if (!(node instanceof Map)) { problems << (path + ': a filter node must be an object'); return null }
    def op = (node.op == null) ? '' : String.valueOf(node.op).trim().toUpperCase()
    def field = (node.field == null) ? '' : String.valueOf(node.field).trim()
    def vals = (node.values instanceof List) ? node.values : []
    if (field.isEmpty()) {
        if (op != 'AND' && op != 'OR') { problems << (path + ': a group needs op AND or OR'); return null }
        def kids = []
        vals.eachWithIndex { ch, i -> def k = toLeaf(ch, path + '.' + i); if (k != null) kids << k }
        return kids.isEmpty() ? null : [operator: op, filters: kids]
    }
    def kind = FIELDS[field]
    if (kind == null) { problems << (path + ': "' + field + '" is not a filterable field'); return null }
    def allowed = (kind == 'NUMBER') ? NUM_OPS : ((kind == 'DATE') ? DATE_OPS : TEXT_OPS)
    if (!allowed.contains(op)) { problems << (path + ': operator "' + op + '" is not supported on ' + field); return null }
    def num = { v -> def t = String.valueOf(v).trim(); (t ==~ /^-?\d+$/) ? Long.valueOf(t) : t }
    if (op == 'BETWEEN') {
        if (vals.size() < 2) { problems << (path + ': BETWEEN needs two bounds'); return null }
        return [property: 'properties.' + field, filter: [operator: op, value: [num(vals[0]), num(vals[1])]]]
    }
    if (vals.isEmpty() || String.valueOf(vals[0]).trim().isEmpty()) { problems << (path + ': needs a value'); return null }
    def out = (kind == 'NUMBER' || kind == 'DATE') ? num(vals[0]) : String.valueOf(vals[0]).trim()
    return [property: 'properties.' + field, filter: [operator: op, value: out]]
}
if (wire != null) {
    def built = toLeaf(wire, 'filter')
    if (!problems.isEmpty()) { valid = false; reason = problems.join('; ') }
    else if (built != null) leaves << built
}
if (!valid) leaves = [[property:'id', filter:[operator:'EQUAL', value:'__invalid_input__']]]
return [valid: valid, reason: reason, filter: [operator:'AND', filters: leaves],
        pageLimit: pageLimit, pageOffset: pageOffset]
